INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(974, 'plPL', 'W poszukiwaniu źródła', 'Tutejsze gorące źródła są dla mnie zagadką. Skąd bierze się to ciepło?$B$BPatrząc, jak blisko Grani Ognistej Smugi leżą te sadzawki, naprawdę się zastanawiam, czy wulkan nie ma z tym czegoś wspólnego. Skonstruowałem termometr do mierzenia temperatury przy wulkanie i chciałbym znaleźć najgorętsze miejsce. Podaje pomiary w stopniach Kraklenheita!$B$BProszę, weź go i mierz temperaturę na grani za każdym razem, gdy zobaczysz gorące miejsce!', 'Krakle z Krateru Un\'Goro chce, abyś $gznalazł:znalazła; najgorętsze miejsce na Grani Ognistej Smugi.$B$BGdy natrafisz na gorące miejsce, kliknij prawym przyciskiem myszy termometr, aby sprawdzić temperaturę. Szukaj dalej, aż znajdziesz najgorętsze.', '', 'Wróć do Krakle\'a przy Gorących Źródłach Golakka w Kraterze Un\'Goro.', 'Znajdź najgorętsze miejsce na Grani Ognistej Smugi', '', '', '', 0),
(980, 'plPL', 'Nowe źródła', 'Słyszałem o innych gorących źródłach w miejscu zwanym Zimozdrojem, daleko na północ stąd. Dziwne jest to, że w ich pobliżu nie ma żadnych wulkanów. Wiem, ciekawe.$B$BJeśli chcesz dowiedzieć się więcej, udaj się do Zimozdroju i porozmawiaj z moją przyjaciółką. Nazywa się Donova Snowden i obecnie przebywa przy tamtejszych gorących źródłach.$B$BJeszcze raz dzięki za pomoc z termometrem! Do zobaczenia!', 'Udaj się do Zimozdroju i porozmawiaj z Donovą Snowden.', '', '', '', '', '', '', 0),
(3844, 'plPL', 'Tajemnica dla wszystkich', 'Na brzegu leży zniszczona tratwa. Skoro to tylko mały staw, trudno powiedzieć, jak się tu znalazła, choć drzewa podpowiadają, że poziom wody bywa różny.$B$BByć może rozejrzenie się po okolicy pozwoli odkryć więcej wskazówek...', 'Poszukaj w stawie wskazówki, do kogo może należeć rozbita tratwa.', '', '', '', '', '', '', 0),
(3845, 'plPL', 'Tajemnica dla wszystkich', 'Chwytasz tobołek i wyciągasz go na brzeg. Może jeśli obejrzysz przedmioty w środku, dowiesz się więcej o jego właścicielu.$B$BW Schronieniu Marshala jest kilku zabłąkanych podróżnych. Może tam dowiesz się czegoś więcej.', 'Obejrzyj przedmioty w tobołku i zanieś je właścicielowi.', '', 'Wróć do Linkena w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(3881, 'plPL', 'Ratunek dla ekspedycji', 'Nie wiem, jak tu $gdotarłeś:dotarłaś;, ale aż miło na ciebie popatrzeć! Jestem Williden Marshal i prowadzę niezależną grupę ekspedycyjną. Nasze najnowsze i największe przedsięwzięcie spotkało, zdawałoby się, niezliczone nieszczęścia, a najpoważniejsze z nich to to, że nie doceniliśmy dzikości Krateru Un\'Goro!$B$BUciekając z naszych obozów w południowo-zachodniej i północno-wschodniej części krateru, zostawiliśmy tam niezbędne zapasy. Wyglądasz na kogoś, kto sobie poradzi – pomożesz nam je odzyskać?', 'Przynieś skrzynię z żywnością i sprzęt badawczy Willidenowi Marshalowi w Kraterze Un\'Goro.', '', 'Wróć do Willidena Marshala w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(3882, 'plPL', 'Rzut kośćmi', 'Można by pomyśleć, że skoro jestem głównym kopaczem Ekspedycji Marshala, to lubię kopać. Może są na tym świecie gorsze zajęcia... ale żadne nie przychodzi mi do głowy.$B$BMieliśmy kopać w Wybiegu dla Grozy – FANTASTYCZNA nazwa, swoją drogą – w poszukiwaniu martwych stegodonów i diemetradonów. No cóż, żywych też jest tam mnóstwo! Wil i Hol wciąż palą się do badania tej śmiertelnej pułapki, więc potrzebujemy tych kości dinozaurów. Ale tak między nami, kości z żywych też się nadadzą.', 'Przynieś 8 kości dinozaurów Sparkowi Nilminerowi w Kraterze Un\'Goro.', '', 'Wróć do Sparka Nilminera w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(3883, 'plPL', 'Obca ekologia', 'To, że ponieśliśmy porażkę, nie znaczy, że badania muszą stanąć! Zanim tu utknęliśmy, badaliśmy owady Gorishi w południowej części krateru. Ich obecność jest obca ekologii Un\'Goro i chcemy się dowiedzieć, skąd się tu wzięły.$B$BW ich roju muszą być wylęgarnie larw. Rozpoznasz je po zwisających skupiskach larw. Użyj tej fiolki, by pobrać próbkę ściany roju w pobliżu którejś z wylęgarni. Przynieś mi ją do zbadania, ale uważaj!', 'Użyj fiolki do skrobania, aby pobrać próbkę ściany roju w jednej z wylęgarni roju Gorishi w Kraterze Un\'Goro. Szukaj komór ze zwisającymi skupiskami larw.$B$BZanieś próbkę ściany roju Hol\'anyee Marshal w Kraterze Un\'Goro.', '', 'Wróć do Hol\'anyee Marshal w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(3884, 'plPL', 'Dziennik Willidena', '$GOdkryłeś:Odkryłaś; poszarpany dziennik. Część wciąż da się odczytać, a jako właściciel podpisał się niejaki Williden Marshal. Jeśli zapiski są dokładne, Willidena można znaleźć gdzieś w północnej części krateru; według dziennika on i jego towarzysze szukali schronienia przed dzikimi bestiami krateru na wyżej położonym terenie, gdy ich obozy zostały opanowane.', 'Zwróć dziennik Willidenowi Marshalowi, który przebywa gdzieś w Kraterze Un\'Goro.', '', '', '', '', '', '', 0),
(3908, 'plPL', 'Tajemnica dla wszystkich', 'Widzisz, nie mam pojęcia, jak się tu znalazłem. Nikt tego tak naprawdę nie wie – to tajemnica dla wszystkich! Po prostu nic nie mogę sobie przypomnieć...$B$BAle te rzeczy, które mi $gprzyniosłeś:przyniosłaś;... Coś mi się przypomina.$B$BMój miecz. Mam go jakoś wzmocnić, ale naprawdę nie wiem po co. Przykro mi, że nie powiem ci więcej, ale po prostu nie pamiętam!$B$BTak czy owak, wiem, dokąd możesz go zanieść – do Donovy Snowden w Zimozdroju. Znajdziesz ją przy gorących źródłach. Może zahartować miecz w tamtejszych sadzawkach.', 'Zanieś miecz Linkena Donovie Snowden w Zimozdroju.', '', '', '', '', '', '', 0),
(3941, 'plPL', 'Pomoc gnomki', 'Myślę... Myślę... Wiem, że przybyłem tu po coś ważnego...$B$BMam pomysł, $N. W tamtej jaskini mieszka gnomka imieniem J.D., która była dla mnie bardzo miła, kiedy tu przybyłem. Może w stanie oszołomienia coś jej powiedziałem.$B$BMoże pójdziesz ją zapytać, czy coś wie? Och, ale uważaj – ona ciągle majstruje przy tych zwariowanych, świecących kryształach, które widziałem w kraterze. Nie mam pojęcia, co ona tam kombinuje!', 'Znajdź J.D. Collie w jaskini w Schronieniu Marshala.', '', '', '', '', '', '', 0),
(3961, 'plPL', 'Przygoda Linkena', 'Pomyśleć, że Linken przez cały ten czas był tu po to, by uwolnić nas od Żarobiega... Wygląda na takiego zwyczajnego gościa, ale zauważyłam, że w ogóle nie interesują go moje eksperymenty ani gadżety, w przeciwieństwie do większości gnomów. W głębi serca musi być prawdziwym wojownikiem.$B$BZanieś mu totem. Zobacz, czy pomoże mu to przypomnieć sobie, po co tu przybył.', 'Zanieś Srebrny totem Aquementasa Linkenowi w Schronieniu Marshala.', '', '', '', '', '', '', 0),
(3962, 'plPL', 'Niebezpiecznie iść samemu', '$N, w końcu sobie przypomniałem... Naprawdę przybyłem tu walczyć z Żarobiegiem. Byłem w podróży, a to miał być jej ostatni etap.$B$BAle to już nie ja jestem bohaterem... Ty nim jesteś. Po wszystkim, czego $gdokonałeś:dokonałaś; – to ty musisz to teraz zakończyć, nie ja.$B$BŻarobieg strzeże artefaktu zwanego Złotym płomieniem. Daje on moc większą niż cokolwiek, co kiedykolwiek poznałem, i jest niebezpieczny w rękach kogoś o złym sercu.$B$BWeź ze sobą innych – niebezpiecznie iść samemu. Weź to sobie do serca.', 'Udaj się na Grań Ognistej Smugi, na południe od Schronienia Marshala.$B$BZnajdź Żarobiega i użyj totemu, by zdjąć jego ochronną aurę. Gdy go pokonasz, zabierz Złoty płomień z jaskini.', '', 'Wróć do Linkena w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(4145, 'plPL', 'Larion i Muigin', 'Widzisz tam Muigina? To przez NIEGO się zgubiliśmy!$B$BTo ja znałem drogę, ale on się uparł, że zna skrót, i wylądowaliśmy tutaj!$B$BNa domiar złego teraz ciągle nasyła na mnie te swoje zwariowane roślinne szkodniki. Jestem tak zły, że nie zamierzam się do niego prędko odezwać, ale z tymi szkodnikami nie daję już sobie rady.$B$BMoże na początek spróbujemy ograniczyć mu zapasy? Idź zapoluj na krwawopłatki, a potem wróć do mnie.', 'Upoluj 5 krwawopłatków smagaczy, 5 krwawopłatków młocarzy, 5 krwawopłatków oprawców i 5 krwawopłatków sidlarzy dla Lariona w Schronieniu Marshala.', '', 'Wróć do Lariona w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(4148, 'plPL', 'Porażacz krwawopłatka', '', '', '', 'Wróć do Lariona w Kraterze Un\'Goro.', '', '', '', '', 0),
(4243, 'plPL', 'W pogoni za A-Me 01', 'Niestety, coś się stało z jednym z moich największych wynalazków. $GWidziałeś:Widziałaś; mechaniczne wiewiórki, prawda? Otóż, żeby zbliżyć się do małp z Krateru Un\'Goro, zbudowałam mechaniczną małpę, która miała wtopić się w ich stado – nazywam ją A-Me 01.$B$BZamiast oczu ma kamienie wróżenia, więc widziałam wszystko to, co ona. Dotarła do Grzybiej Skały – legowiska małp – na wschód stąd i wtedy straciłam z nią kontakt. Ostatnie, co widziałam, to jeden z ich samców alfa pędzący, by się z nią przywitać!$B$BPomożesz mi ją odnaleźć?', 'Odnajdź A-Me 01 w Kraterze Un\'Goro.', '', '', '', '', '', '', 0),
(4244, 'plPL', 'W pogoni za A-Me 01', 'Dalsze oględziny ujawniają odsuwany panel. Nad przewodami widnieje wyraźny napis: „Wymienić mithrilową obudowę, wyłączyć i włączyć zasilanie”.$B$BZasuwając panel z powrotem, zastanawiasz się, czy naprawa A-Me 01 i odprowadzenie jej do Karny Remtravel w pobliżu Schronienia Marshala będzie aż tak proste.$B$BPrzekonasz się, dopiero gdy spróbujesz.', 'Znajdź mithrilową obudowę i wróć do A-Me 01 w Kraterze Un\'Goro.', '', 'Wróć do A-Me 01 w Kraterze Un\'Goro.', '', '', '', '', 0),
(4245, 'plPL', 'W pogoni za A-Me 01', 'Upewniwszy się, że jesteś $ggotów:gotowa; odprowadzić A-Me 01 do Karny Remtravel, przestawiasz przełącznik w pozycję „Wył.”. Rozglądasz się jeszcze raz, czy nie nadchodzą goryle, i szykujesz się, by zobaczyć, co się stanie, gdy przestawisz przełącznik z powrotem na „Wł.”.$B$BTo twoja ostatnia szansa... czy na pewno tego chcesz?', 'Odeskortuj A-Me 01 z powrotem do Karny Remtravel w Kraterze Un\'Goro.', 'Chroń A-Me 01, dopóki nie dotrzesz do Karny Remtravel', 'Wróć do Karny Remtravel przy Smolistych Dołach Lakkari w Kraterze Un\'Goro.', '', '', '', '', 0),
(4289, 'plPL', 'Małpy z Un\'Goro', 'W tym kraterze żyje wiele dziwnych stworzeń – zdają się szlachetniejszymi odmianami istot, które spotyka się w mojej ojczyźnie i poza nią. Nie potrafię tego wyjaśnić, ale to miejsce woła głosem Matki Ziemi. Oddaję jej cześć za każdym razem, gdy tropię jedno z jej pięknych stworzeń w tej niecce.$B$BJeśli ty także pragniesz zaznać oświecenia, które towarzyszy takiemu wyczynowi, udaj się na północ. Znajdziesz tam wielkie małpy, które wystawią na próbę siłę każdego śmiertelnika. Przynieś mi ich futra... udowodnij swoją siłę.', 'Przynieś 2 futra goryla z Un\'Goro, 2 futra deptacza z Un\'Goro i 2 futra gromiciela z Un\'Goro Torwie Tropicielowi u wejścia do Krateru Un\'Goro.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(4290, 'plPL', 'Strawa Lar\'korwiego', 'Dawno temu jeden z moich braci zabrał trochę mięsa z ofiary Lar\'korwiego. Nie wiedział wtedy, że Lar\'korwi obserwuje go z lasu. Lar\'korwi całymi dniami szedł za moim bratem, niszcząc wszystko, czego ten dotknął. Przerażony brat w końcu postanowił uciec z krateru i zostawić Lar\'korwiego za sobą.$B$BLar\'korwi zabił go niedaleko tego miejsca.$B$BJeśli chcesz sprowokować Lar\'korwiego, znajdź jego świeżą zdobycz i weź z niej trochę mięsa.$B$BPotem wróć do mnie.', 'Znajdź truchło najświeższej ofiary Lar\'korwiego i ukradnij kawałek truchła threshadona, a potem wróć do Torwy Tropiciela w Kraterze Un\'Goro.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(4291, 'plPL', 'Woń Lar\'korwiego', 'Szczerze mówiąc, dziwię się, że jeszcze po ciebie nie przyszedł, $N. Ale nic straconego, bo mam ostatni plan, który sprowadzi do nas potwora.$B$BJako dominujący samiec Lar\'korwi ma prawo parzyć się z każdą samicą, jaką wybierze – a wybiera ich wiele. Na zachód stąd znajdziesz mnóstwo jaj plądrozaurów. Zbliż się do nich, a jego partnerki powinny cię zaatakować. Samice wydzielają okropny zapach z gruczołu w głowie, który daje samcom znać, że są gotowe do rozrodu. Przynieś mi dwa takie gruczoły.', 'Przynieś 2 gruczoły feromonowe plądrozaura Torwie Tropicielowi w pobliżu wejścia do Krateru Un\'Goro.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(4292, 'plPL', 'Przynęta na Lar\'korwiego', 'To będzie najtrudniejsza część, bo plan jest nieco skomplikowany. Na północ stąd znajdziesz wąską ścieżkę w góry. To tam ostatnio widziałem Lar\'korwiego. Poznasz, że jesteś we właściwym miejscu, po kościach ogromnych stworzeń, które niegdyś tamtędy wędrowały. Weź odzyskane mięso i połóż je tam. Potem natrzyj je tą mieszanką, którą przygotowałem. Jeśli obie przynęty razem nie przywabią Lar\'korwiego, to nie znam innego sposobu.', 'Za pomocą zawartości sakiewki Torwy przywołaj Lar\'korwiego i pokonaj go. Następnie zanieś głowę Lar\'korwiego Torwie Tropicielowi w pobliżu wejścia do Krateru Un\'Goro.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(4301, 'plPL', 'Potężny U\'cha', 'Gdy $gbadałeś:badałaś; Un\'Goro, widziałem inne rzeczy, które ucieszyłyby $gtakiego potężnego łowcę:taką potężną łowczynię; jak ty. Jedną z nich była ogromna małpa pośród innych goryli na północy. $GByłeś:Byłaś; już w tamtej jaskini, ale jeśli przyjmiesz moje zadanie, zastanawiam się, czy tym razem przeżyjesz to spotkanie.$B$BNazywam go U\'cha i jest jednym z największych synów Matki Ziemi, tego możesz być $gpewien:pewna;. Pokonaj U\'chę i przynieś mi jego futro. Zrób to, a będę bronić twojego prawa do nazywania się $gwielkim łowcą:wielką łowczynią;.', 'Przynieś futro U\'chy Torwie Tropicielowi u wejścia do Krateru Un\'Goro.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(4321, 'plPL', 'Rozgryźć zagadkę', 'Informacje, które mi $gprzekazałeś:przekazałaś; o pylonach, są bardzo ciekawe...$B$BDaj mi chwilę na obliczenia, $N. Porozmawiaj ze mną za moment, a powinnam móc dać ci odpowiedź, której szukaliśmy.', 'Za chwilę porozmawiaj z J.D. Collie.', '', '', '', '', '', '', 0),
(4381, 'plPL', 'Kryształowe odnowienie', '', '', '', 'Wróć do Północnego kryształowego pylonu w Kraterze Un\'Goro.', '', '', '', '', 0),
(4382, 'plPL', 'Kryształowa siła', '', '', '', 'Wróć do Wschodniego kryształowego pylonu w Kraterze Un\'Goro.', '', '', '', '', 0),
(4383, 'plPL', 'Kryształowa osłona', '', '', '', 'Wróć do Zachodniego kryształowego pylonu w Silithusie.', '', '', '', '', 0),
(4384, 'plPL', 'Kryształowy plon', '', '', '', 'Wróć do Zachodniego kryształowego pylonu w Silithusie.', '', '', '', '', 0),
(4385, 'plPL', 'Kryształowy ładunek', '', '', '', 'Wróć do Północnego kryształowego pylonu w Kraterze Un\'Goro.', '', '', '', '', 0),
(4386, 'plPL', 'Kryształowa iglica', '', '', '', 'Wróć do Wschodniego kryształowego pylonu w Kraterze Un\'Goro.', '', '', '', '', 0),
(4491, 'plPL', 'Z niewielką pomocą przyjaciół', 'Uch... Jak gorąco...$B$BZwiedzałem tę okolicę, gdy nagle upał stał się nie do zniesienia. Chyba dostałem udaru cieplnego.$B$BProszę, pomóż mi wrócić do mojej przyjaciółki Spraggle w Schronieniu Marshala. Chyba czuję się na tyle dobrze, żeby pójść za tobą.$B$BJestem trochę otępiały, więc jeśli znowu zemdleję, po prostu chlapnij na mnie wodą z manierki Spraggle. To powinno pomóc, mam nadzieję...', 'Zaprowadź Ringo do Spraggle Frock w Schronieniu Marshala.$B$BJeśli Ringo zemdleje, ocuć go wodą z manierki Spraggle.', 'Odeskortuj Ringo do Spraggle Frock w Schronieniu Marshala', 'Wróć do Spraggle Frock w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(4492, 'plPL', 'Zgubiony!', 'Musisz mi pomóc, $N! Mój przyjaciel Ringo wybrał się wcześniej zbadać wulkan na południe stąd i nie ma go już stanowczo za długo. Naprawdę się o niego martwię.$B$BDasz radę go odnaleźć? Weź ze sobą moją manierkę – jeśli znajdziesz Ringo, na pewno będzie jej potrzebował!', 'Znajdź Ringo na Grani Ognistej Smugi.', '', '', '', '', '', '', 0),
(4501, 'plPL', 'Uwaga na pterrordaksy', 'Poszukiwany wprawny wojownik, który upora się z zagrożeniem ze strony pterrordaksów zamieszkujących Krater Un\'Goro. Jest ich coraz więcej i stają się plagą dla podróżnych w okolicy.$B$BZmniejsz ich liczebność, zabijając 10 rozszalałych pterrordaksów.$B$BPo wykonaniu zadania porozmawiaj ze Spraggle Frock, by odebrać nagrodę.', 'Zabij 10 rozszalałych pterrordaksów, a następnie porozmawiaj ze Spraggle Frock w Schronieniu Marshala.', '', 'Wróć do Spraggle Frock w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(4503, 'plPL', 'Latadło Shizzle', 'Buduję maszynę latającą!$B$BUtknąłem tutaj, a z orientacją w terenie jestem beznadziejny. Poleciałbym na gryfie albo wiwernie z powrotem do Gadżetonu, ale te bestie śmiertelnie mnie przerażają.$B$BTo jak, pomożesz mi? Zostały mi już tylko skrzydła i pomyślałem, że łuski pterrordaksów i diemetradonów w pajęczynie będą idealne. Nie ma mowy, żebym sam zmierzył się z którymś z nich, ale ty wyglądasz na $gtwardziela:twardzielkę;. Może spróbujesz?', 'Zbierz 8 łusek diemetradona w pajęczynie i 8 łusek pterrordaksa w pajęczynie dla Shizzle w Schronieniu Marshala.', '', 'Wróć do Shizzle w Schronieniu Marshala w Kraterze Un\'Goro.', '', '', '', '', 0),
(4842, 'plPL', 'Dziwne źródła', 'Prawdę mówiąc, choć w Zimozdroju nie ma wulkanów, uważam, że te gorące źródła mają o wiele groźniejsze przyczyny...$B$BCóż, chyba zechcesz zobaczyć to na własne oczy. Musisz przemierzyć cały Zimozdrój i dotrzeć na samo południe. Kiedy powietrze zrobi się gęste i parne, a niebo pociemnieje, znajdziesz to, co moim zdaniem jest źródłem gorących źródeł.$B$BRozejrzyj się tam. Na pewno po powrocie będziesz mieć wiele pytań.', 'Postępuj zgodnie ze wskazówkami Donovy Snowden, a potem zamelduj się u niej.', 'Odkryj Wąwóz Mrocznego Szeptu', 'Wróć do Donovy Snowden w Zimozdroju.', '', '', '', '', 0),
(5082, 'plPL', 'Zagrożenie ze strony Zimospadu', 'Przyjechałam do Zimozdroju, żeby zbadać Gorące Źródła Mroźnego Ognia. Zauważyłam, że woda zdaje się mieć... dziwne właściwości. Nie udało mi się jeszcze odkryć, skąd się to bierze, a prawdę mówiąc, ostatnio mam trochę kłopotów z powodu furbolgów z plemienia Zimospadu.$B$BWygląda na to, że źródła przyciągają ich tak samo jak mnie. Strasznie zawzięcie strzegą wody i nie pozwalają mi zbliżyć się do dwóch większych źródeł na północ stąd.$B$BChciałabym kontynuować badania. Pomożesz mi?', 'Donova Snowden z Zimozdroju chce, abyś $gzabił:zabiła; 8 odkrywców Zimospadu, 8 strażników legowiska Zimospadu i 8 totemistrzów Zimospadu.', '', 'Wróć do Donovy Snowden w Zimozdroju.', '', '', '', '', 0),
(5086, 'plPL', 'Toksyczne monstra', 'Zbadałam próbkę, którą $gprzyniosłeś:przyniosłaś;, i choć nie mogę mieć pewności, sądzę, że zawiera ślady toksycznych pierwiastków. Jedynym sposobem, by się upewnić, jest zdobycie próbek do porównania.$B$BPodejrzewam, że furbolgi z plemienia Martwego Drewna mogą pozyskiwać te pierwiastki z innych splugawionych stworzeń w Spaczonej Kniei, a zwłaszcza z żywiołaków żyjących w Lesie Żelaznych Drzew, zwanych toksycznymi monstrami.$B$BZbierz dla mnie kilka próbek do porównania, ale uważaj – tam jest bardzo niebezpiecznie!', 'Zbierz 3 krople toksycznego monstrum dla Donovy Snowden w Zimozdroju.', '', 'Wróć do Donovy Snowden w Zimozdroju.', '', '', '', '', 0),
(5087, 'plPL', 'Biegacze Zimospadu', 'Bardzo ciekawe, $N...$B$BGdy tę toksyczną substancję zmiesza się z wodą z gorących źródeł, traci swoją toksyczność i zachowuje jedynie zdolność chwilowego oddziaływania na tych, którzy ją spożyją. To dlatego furbolgi z Zimospadu tak zaciekle strzegą gorących źródeł – potrzebują ich, by oczyszczać swoją ognistą wodę.$B$BMusimy to powstrzymać – przerwać kontakt między Zimospadem a Martwym Drewnem. Grupa biegaczy kursuje między ich wioską a Spaczoną Knieją. Znajdź ich, pokonaj i ukradnij im przesyłkę.', 'Znajdź biegaczy Zimospadu i nie pozwól im dostarczyć przesyłki do Wioski Zimospadu.', '', 'Wróć do Donovy Snowden w Zimozdroju.', '', '', '', '', 0),
(5121, 'plPL', 'Najwyższy Wódz Zimospadu', 'Choć wciąż niewiele wiemy o tym, dlaczego furbolgi spożywają tę dziwną substancję, uważam, że najlepiej będzie to powstrzymać, zanim wymknie się spod kontroli.$B$BFurbolgi z Zimospadu nie są zwykle agresywnym plemieniem, a ta zmiana w ich zachowaniu każe mi sądzić, że działają na rozkaz swojego wodza. Szkód, które już się stały, raczej nie da się cofnąć, ale myślę, że jeśli ich przywódca zginie, nie będzie gorzej.$B$BUdaj się na wschód, do Wioski Zimospadu.', 'Donova Snowden z Zimozdroju chce, abyś $gpokonał:pokonała; Najwyższego Wodza Zimospadu.', '', 'Wróć do Donovy Snowden w Zimozdroju.', '', '', '', '', 0),
(5150, 'plPL', 'Dadanga jest głodna!', '', '', '', 'Wróć do Dadangi.', '', '', '', '', 0),
(8681, 'plPL', 'Nestor Gromoróg', '', '', '', '', '', '', '', '', 0),
(9051, 'plPL', 'Toksyczny test', 'Toksyna, którą $gpomogłeś:pomogłaś; mi stworzyć, ma szczególne przeznaczenie. Przez wielkie diabłozaury z krateru polowanie tu jest niebezpieczne, a przetrwanie trudne. Nawet gdybym miał dość siły, zabicie diabłozaura sprawia tylko, że na jego terytorium wkracza kolejny.$b$bWeź ten zatruty kolec i wbij go głęboko w żywego diabłozaura. Toksyna powinna uspokoić stworzenie, choć nie wiem, jak szybko...', 'Dźgnij diabłozaura kolcem diabłozaura. Po wykonaniu zadania wróć do Torwy Tropiciela w Kraterze Un\'Goro.', 'Diabłozaur dźgnięty kolcem', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(9052, 'plPL', 'Trucizna krwawopłatka', 'Chciałbym poprosić cię o pomoc w stworzeniu pewnej toksyny, która uspokoi wielkie stworzenie żyjące tu, w kraterze. Nie jest śmiertelna, a składniki zdoła zebrać tylko ktoś o tak bystrym oku jak ty.$b$bGrzyby zwane krwawymi czapkami rosną w kiełkach krwawopłatka w całym kraterze. Żądła Gorishi zdobędziesz od owadów w Pełzającej Bliźnie i wokół niej, w południowej części krateru.', 'Zbierz 8 krwawych czapek i 8 żądeł Gorishi, a następnie wróć do Torwy Tropiciela w Kraterze Un\'Goro.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(9053, 'plPL', 'Lepszy składnik', 'Stało się, czego się obawiałem – toksyna jest po prostu za słaba na tak potężne stworzenie.$b$bJeśli mamy stworzyć dość silną toksynę, musisz zejść na samo dno Świątyni Atal\'Hakkar, odkryć tajemnice ołtarza i zdobyć gnijące pnącze od tamtejszego strażnika. Świątynia jest niebezpieczna, więc lepiej weź ze sobą przyjaciół.$b$bWróć do mnie, gdy to zrobisz.', 'Zdobądź gnijące pnącze od strażnika na dnie Zatopionej Świątyni i wróć do Torwy Tropiciela.', '', 'Wróć do Torwy Tropiciela na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(12547, 'plPL', 'Runa aktywacji', 'Ta kolosalna istota wydaje się nieaktywna. Na jej piersi dostrzegasz puste gniazdo w kształcie runy.$B$BByć może brakującą runę znajdziesz we wnętrzu pobliskiego tarasu.', 'Zdobądź Runę omega z wnętrza Tarasu Kształtującego i zanieś ją Etymidianowi.', '', 'Wróć do Etymidiana w Kraterze Un\'Goro.', '', '', '', '', 0),
(12548, 'plPL', 'Etymidian', 'Nadszedł czas, $N. Wrota Przejścia zostały uaktywnione po raz pierwszy od siedmiu stuleci. Użyj ich, by udać się tam, gdzie leży nasza ostatnia nadzieja.$B$BPołóżmy kres tym, którzy chcą skazić tę nieskalaną krainę plagą nieumarłych. Uwolnijmy Etymidiana.', 'Przejdź przez Wrota Przejścia na południowym krańcu Kotliny Sholazar i poszukaj po drugiej stronie broni zwanej Etymidianem.', '', '', '', '', '', '', 0),
(12797, 'plPL', 'Z powrotem przez Wrota Przejścia', 'Mówisz prawdę. Wyczuwam, jak sama istota Kotliny Sholazar zaczyna się strzępić pod wpływem zarazy nieumarłych, nawet teraz, gdy rozmawiamy.$B$BZwiązałem swój byt z runą. Zanieś ją tej, która cię tu przysłała – tylko jej moc może mi otworzyć drogę do jej krain.', 'Zanieś Runę omega Awatarowi Frei przy Bystrzynie Deszczomówców w Kotlinie Sholazar.', '', 'Wróć do Awatara Frei przy Bystrzynie Deszczomówców w Kotlinie Sholazar.', '', '', '', '', 0),
(13850, 'plPL', 'Odporność na toksyny', 'Chcesz jeździć na jadoskórym? To mam dla ciebie złe wieści.$B$BJadoskóre plądrozaury to sama trucizna: trująca krew, trująca ślina, trująca skóra. Wsiądziesz na takiego, a po kilku godzinach spadniesz $gmartwy:martwa;.$B$BZanim bym ci któregoś sprzedał, $gmusiałbyś:musiałabyś; nabrać odporności na ich toksyny, a to trwa długo, BARDZO długo... musiałaby cię wiele razy ochlapać trująca krew w walce z nimi. Jeśli naprawdę cię to interesuje, jadoskóre wolą północną część Moczarów, na północny zachód stąd.', 'Mor\'vek z Krateru Un\'Goro twierdzi, że jeśli 20 razy zatruje cię krew jadoskórego plądrozaura, będziesz $gmógł:mogła; na nim jeździć i nie zginąć. Atakuj jadoskóre plądrozaury, by mieć szansę na zatrucie.', '', 'Wróć do Mor\'veka na Moczarach w Kraterze Un\'Goro.', 'Ochlapanie krwią jadoskórego', '', '', '', 0),
(13887, 'plPL', 'Jaja jadoskórych', 'Skoro już $gnabrałeś:nabrałaś; odporności na toksynę jadoskórych, możesz bezpiecznie obchodzić się z tymi zwierzętami i ich jajami. Jadoskóre są zajadłe i trzeba je tresować od chwili wyklucia.$B$BJeśli chcesz na jednym jeździć, potrzebujesz niewyklutego jaja. Na całych Moczarach rozsiane są gniazda plądrozaurów. Szukaj jaj o jaśniejszych skorupkach – to z nich wykluwają się jadoskóre.$B$BJeśli przyniesiesz mi kilka jaj, pozwolę ci jedno zatrzymać i pod moim okiem wychować pisklę.', 'Przynieś 4 jaja jadoskórego plądrozaura Mor\'vekowi w południowo-wschodniej części Moczarów.', '', 'Wróć do Mor\'veka na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(13889, 'plPL', 'Głodne, głodne pisklę', 'Pisklę jadoskórego patrzy na ciebie wyczekująco, po czym zaczyna rysować w ziemi piktogram.$B$BRysunki są niezgrabne, ale rozpoznajesz kształty diemetradonów, stegodonów i pterrordaksów. Gdy raptor kończy szkic, podnosi na ciebie wzrok, szczerzy zęby i kłapie szczęką.$B$BTwoje pisklę jadoskórego musi mieć chrapkę na świeże mięso tych zwierząt. Znajdź i zabij dowolnego diemetradona, stegodona lub pterrordaksa w Kraterze Un\'Goro i nakarm jego mięsem swoje głodne pisklę.', 'Twoje pisklę jadoskórego chce, żebyś $gnakarmił:nakarmiła; je 15 kawałkami świeżego mięsa dinozaura.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', 'Pisklę jadoskórego nakarmione świeżym mięsem dinozaura', '', '', '', 0),
(13903, 'plPL', 'Gorishi na ząb', 'Pisklę jadoskórego patrzy na ciebie wyczekująco, po czym zaczyna rysować w ziemi piktogram.$B$BRysunki pisklęcia przypominają różne duże owady, być może silithidy Gorishi. Pisklę kończy obrazek, wskazuje go krótką łapką, kłapie szczękami i oblizuje się.$B$BMusi chcieć, żebyś $gudał:udała; się do Pełzającej Blizny, pośrodku południowej części Krateru Un\'Goro, i $gzebrał:zebrała; mięso silithidów. Gdy je zdobędziesz, nakarm nim swoje głodne pisklę.', 'Twoje pisklę jadoskórego chce, żebyś $gnakarmił:nakarmiła; je 10 kawałkami mięsa silithida.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', 'Pisklę jadoskórego nakarmione mięsem silithida', '', '', '', 0),
(13904, 'plPL', 'W koszulce, jajecznica czy na surowo?', 'Pisklęciu jadoskórego burczy w brzuchu, gdy próbuje zwrócić na siebie twoją uwagę. Zaczyna rysować w ziemi silithidy, a pod nimi małe owale. Patrzy na ciebie z nadzieją i wskazuje kółka.$B$BTo mogą być tylko jaja silithidów. Trujące Leże w zachodnim Tanaris, blisko granicy z Kraterem Un\'Goro, to pewnie świetne miejsce, by znaleźć jaja, których chce twoje maleństwo.', 'Twoje pisklę jadoskórego chce, żebyś $gnakarmił:nakarmiła; je 12 jajami silithida.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', 'Pisklę jadoskórego nakarmione jajami silithida', '', '', '', 0),
(13905, 'plPL', 'Pióra palącego roka', 'Pisklę przez chwilę na ciebie patrzy, jakby się zastanawiało, czy zrozumiesz. Rysuje w ziemi parę piór, a potem wskazuje pazurem wiązania na swoich łokciach i kolanach.$B$BNie wygląda na głodne, ale do czego mogą mu być potrzebne pióra?$B$BPewnie chce ich jako ozdób, takich jak te, które $gwidziałeś:widziałaś; u innych raptorów. Największe pióra mają palące roki, które gromadzą się wokół kości wielkich stworzeń w zachodnim Tanaris, na północny wschód od Doliny Ostowych Krzewów.', 'Twoje pisklę jadoskórego chce, żebyś $gzdobył:zdobyła; 5 sztuk upierzenia palącego roka.', '', 'Wróć do pisklęcia jadoskórego.', '', '', '', '', 0),
(13906, 'plPL', 'Tak szybko rosną', 'Dzięki twojej fachowej opiece i karmieniu pisklę jadoskórego szybko urośnie. W miarę wzrostu mleczne zęby pisklęcia zastąpią zęby stałe. Jeśli będziesz $gzbierał:zbierała; zęby, które zrzuca, łatwo poznasz, kiedy będzie na tyle dojrzałe, by wytresować je na wierzchowca.$B$BTwój jadoskóry da ci znać, czego potrzebuje, więc uważnie go obserwuj. Gdy zrzuci wszystkie mleczne zęby, wróć do mnie z nim i z materiałami na siodło, a ja zajmę się resztą.', 'Przynieś 20 mlecznych zębów jadoskórego, pisklę jadoskórego, 20 runicznych tkanin, 20 chropowatych skór i 80 sztuk złota Mor\'vekowi w południowo-wschodniej części Moczarów w Kraterze Un\'Goro.', '', 'Wróć do Mor\'veka na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(13908, 'plPL', 'Rynsztunek do jazdy', 'Twój jadoskóry jest silny i zdrowy, a między wami zawiązała się mocna więź. Będziesz $gmógł:mogła; na nim jeździć, gdy tylko skończę siodło i uzdę. Tak jak ty, muszą zostać specjalnie przygotowane, by wytrzymać toksyny wytwarzane przez raptora.$B$BWystarczy, że przyniesiesz mi trochę chropowatej skóry, runicznej tkaniny i pieniądze na resztę materiałów, a siodło będzie gotowe w mig.', 'Przynieś 20 chropowatych skór, 20 runicznych tkanin i 80 sztuk złota Mor\'vekowi w południowo-wschodniej części Moczarów w Kraterze Un\'Goro.', '', 'Wróć do Mor\'veka na Moczarach w Kraterze Un\'Goro.', '', '', '', '', 0),
(13914, 'plPL', 'Pióra palącego roka', 'Pisklę przez chwilę na ciebie patrzy, jakby się zastanawiało, czy zrozumiesz. Rysuje w ziemi parę piór, a potem wskazuje pazurem wiązania na swoich łokciach i kolanach.$B$BNie wygląda na głodne, ale do czego mogą mu być potrzebne pióra?$B$BPewnie chce ich jako ozdób, takich jak te, które $gwidziałeś:widziałaś; u innych raptorów. Największe pióra mają palące roki, które gromadzą się wokół kości wielkich stworzeń w zachodnim Tanaris, na północny wschód od Doliny Ostowych Krzewów.', 'Twoje pisklę jadoskórego chce, żebyś $gzdobył:zdobyła; 5 sztuk upierzenia palącego roka.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', '', '', '', '', 0),
(13915, 'plPL', 'Głodne, głodne pisklę', 'Pisklę jadoskórego patrzy na ciebie wyczekująco, po czym zaczyna rysować w ziemi piktogram.$B$BRysunki są niezgrabne, ale rozpoznajesz kształty diemetradonów, stegodonów i pterrordaksów. Gdy raptor kończy szkic, podnosi na ciebie wzrok, szczerzy zęby i kłapie szczęką.$B$BTwoje pisklę jadoskórego musi mieć chrapkę na świeże mięso tych zwierząt. Znajdź i zabij dowolnego diemetradona, stegodona lub pterrordaksa w Kraterze Un\'Goro i nakarm jego mięsem swoje głodne pisklę.', 'Twoje pisklę jadoskórego chce, żebyś $gnakarmił:nakarmiła; je 15 kawałkami świeżego mięsa dinozaura.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', 'Pisklę jadoskórego nakarmione świeżym mięsem dinozaura', '', '', '', 0),
(13916, 'plPL', 'W koszulce, jajecznica czy na surowo?', 'Pisklęciu jadoskórego burczy w brzuchu, gdy próbuje zwrócić na siebie twoją uwagę. Zaczyna rysować w ziemi silithidy, a pod nimi małe owale. Patrzy na ciebie z nadzieją i wskazuje kółka.$B$BTo mogą być tylko jaja silithidów. Trujące Leże w zachodnim Tanaris, blisko granicy z Kraterem Un\'Goro, to pewnie świetne miejsce, by znaleźć jaja, których chce twoje maleństwo.', 'Twoje pisklę jadoskórego chce, żebyś $gnakarmił:nakarmiła; je 12 jajami silithida.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', 'Pisklę jadoskórego nakarmione jajami silithida', '', '', '', 0),
(13917, 'plPL', 'Gorishi na ząb', 'Pisklę jadoskórego patrzy na ciebie wyczekująco, po czym zaczyna rysować w ziemi piktogram.$B$BRysunki pisklęcia przypominają różne duże owady, być może silithidy Gorishi. Pisklę kończy obrazek, wskazuje go krótką łapką, kłapie szczękami i oblizuje się.$B$BMusi chcieć, żebyś $gudał:udała; się do Pełzającej Blizny, pośrodku południowej części Krateru Un\'Goro, i $gzebrał:zebrała; mięso silithidów. Gdy je zdobędziesz, nakarm nim swoje głodne pisklę.', 'Twoje pisklę jadoskórego chce, żebyś $gnakarmił:nakarmiła; je 10 kawałkami mięsa silithida.', '', 'Porozmawiaj ze swoim pisklęciem jadoskórego.', 'Pisklę jadoskórego nakarmione mięsem silithida', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(974, 'plPL', 'Tak, zdecydowanie widzę tu zależność między temperaturą wulkanu a gorącymi źródłami. Muszę jeszcze sprawdzić, czy moje równania są dokładne, ale wygląda na to, że odległość i tempo przenoszenia ciepła... Hmm...', 0),
(980, 'plPL', 'Witaj, $N. Tak, to, co powiedział ci Krakle, to prawda...', 0),
(3844, 'plPL', 'Na dnie stawu leży przemoknięty tobołek.', 0),
(3845, 'plPL', 'Och... Tak, te rzeczy wyglądają znajomo... no, mniej więcej...', 0),
(3881, 'plPL', '$GOdzyskałeś:Odzyskałaś; zarówno naszą żywność, JAK I sprzęt badawczy! Nie tylko $guratowałeś:uratowałaś; ekspedycję, ale też nasze życie. Ja i reszta mojej ekipy nie wiemy, jak ci dziękować; dzięki tobie może jednak wytrzymamy tu jeszcze jakiś czas.$B$BNiewiele mamy, ale za tak bezcenną pomoc z pewnością nie zostawię cię z pustymi rękami. Dziękuję, $N – w Ekspedycjach Marshala masz przyjaciela!', 0),
(3882, 'plPL', 'Świetnie, te powinny wystarczyć. A teraz, jeśli pozwolisz...$B$BDZIĘKUJEMY ZA WYKOPANIE WSZYSTKICH TYCH KOŚCI Z ZIEMI BEZ KRZYWDZENIA JAKICHKOLWIEK TUTEJSZYCH ZWIERZĄT.$B$BCzy tak było naprawdę, czy nie – nie chcę wiedzieć. I niech tak zostanie, dobrze? Proszę – może dzięki temu nie puścisz pary z ust. Wszystko, byle wyjść stąd żywym, ot co!', 0),
(3883, 'plPL', 'Tak, to się świetnie nada. Bardzo mi $gpomogłeś:pomogłaś;... Chciałabym dać ci coś więcej, ale kiedy się utknęło pośrodku dzikiej krainy, niewiele można dać. Bądź jednak $gpewien:pewna;, że bez twojej pomocy nasze tutejsze badania nie byłyby możliwe!', 0),
(3884, 'plPL', 'No proszę – mój dziennik! Myślałem, że przepadł, jak prawie wszystko, co przywieźliśmy do Un\'Goro. Serdecznie dziękuję, że mi go $goddałeś:oddałaś;!', 0),
(3908, 'plPL', 'Oczywiście, że mogę zahartować ten miecz. Kiedy będę pracować, możesz mi wyjaśnić, czemu Linkenowi zajęło to tyle czasu. Zwykle nie zapomina o takich sprawach...', 0),
(3909, 'plPL', 'Potrzebuję jednej fiolki, żeby się upewnić, że to naprawdę ten eliksir... Tak... To jest to.', 0),
(3941, 'plPL', 'Zostań na chwilę tam, gdzie stoisz... Testuję nowe połączenie kryształów...', 0),
(3961, 'plPL', 'Czy J.D. choć trochę ci pomogła?', 0),
(3962, 'plPL', 'Dziękuję, $N.$B$BZłoty płomień wróci teraz do mojej ojczyzny, gdzie będzie strzeżony i nigdy więcej nie posłuży złu.$B$BTyle dla mnie $gzrobiłeś:zrobiłaś;, że chcę ci to dać. Gdyby nie ty, wciąż nie wiedziałbym, kim jestem!', 0),
(4141, 'plPL', 'Mam nadzieję, że nie sprawiły ci za dużo kłopotu, $N. Staram się trzymać od nich z daleka – są dzikie!$B$BRaz próbowałem przeskoczyć przez jednego... i mnie zaatakował! Rośliny po prostu nie powinny się tak zachowywać!', 0),
(4144, 'plPL', 'Raz kozie śmierć, $N! To przyciągnie uwagę Lariona!', 0),
(4145, 'plPL', 'Dzięki za pomoc, $N, ale obawiam się, że mam złe wieści...', 0),
(4148, 'plPL', 'Wygląda na to, że zadziała idealnie, $N. Pamiętaj tylko: jeśli zobaczysz w pobliżu któregoś z tych szkodników, nie wahaj się użyć porażacza!', 0),
(4243, 'plPL', 'Oglądając A-Me 01, dostrzegasz dwa ogromne wgniecenia szpecące coś, co Karna najwyraźniej uważa za majstersztyk inżynierii. Jedno wgniecenie zdobi ramię A-Me 01, drugie jej głowę.$B$BPrzy dokładniejszych oględzinach okazuje się, że przez jej podzespoły nie płynie żadna energia.', 0),
(4244, 'plPL', 'Znów zdejmujesz panel z pleców A-Me 01 i ostrożnie wyjmujesz starą mithrilową obudowę, która najwyraźniej się przepaliła. Nowa bez trudu wsuwa się na miejsce. Jeśli to obudowa była problemem, pozostaje tylko przestawić przełącznik w pozycję „Wył.”, a potem z powrotem na „Wł.”.', 0),
(4245, 'plPL', 'Och, udało ci się! Cudownie! Dziękuję, $N.$b$bOch, moja biedna A-Me. Spójrz na te wszystkie wgniecenia. Odrobina pracy i znów będzie działać bez zarzutu.$b$bJeszcze raz dziękuję, $N. Naprawdę to doceniam.', 0),
(4284, 'plPL', 'Teraz mogę kontynuować eksperymenty! Dziękuję, $N.', 0),
(4285, 'plPL', 'Wiem, że te opowieści są prawdziwe, $N.', 0),
(4287, 'plPL', 'Un\'Goro to takie dziwne miejsce, $N. Kiedy wchodzisz do krateru, czujesz się, jakbyś $gtrafił:trafiła; do zupełnie innego świata...', 0),
(4288, 'plPL', 'Wzdłuż zboczy krateru jest wiele ukrytych miejsc. Jeśli nie masz pomysłu, gdzie jeszcze szukać, spróbuj zbadać kręte ścieżki, $N.', 0),
(4289, 'plPL', 'A więc $gokazałeś:okazałaś; się $gsilny:silna; – na tyle $gsilny:silna;, by pokonać wielkie małpy z Un\'Goro. To dobrze. To wyzwanie było niczym w porównaniu z Lar\'korwim, ale nie odbiorę ci tak wielkiego zwycięstwa.$B$BZ tych futer powstanie wspaniałe odzienie dla mojego plemienia. $GPomogłeś:Pomogłaś; mi i $gdowiodłeś:dowiodłaś;, że jesteś $ggodzien:godna;.$B$BZanim wyruszysz z kolejnym zadaniem, oddajmy chwałę Matce Ziemi i podziękujmy duchom małp, które $gzabiłeś:zabiłaś; – niech wiedzą, że ich śmierć nie pójdzie na marne.', 0),
(4290, 'plPL', 'To się świetnie nada, $N. Wygląda na to, że Lar\'korwi dobrze się ostatnio odżywia. Choć zastanawiam się, skąd w tej okolicy wziął threshadona. Dziwne.$B$BTak czy inaczej, przechowam to, dopóki nie będziesz $ggotów:gotowa; na starcie z bestią. Nie martw się o moje bezpieczeństwo – jestem pewien, że $grozwścieczyłeś:rozwścieczyłaś; Lar\'korwiego na tyle, że nie zabije mnie, dopóki nie posmakuje twojego ciała.', 0),
(4291, 'plPL', 'Ach, wspaniałe okazy, $N. Te dwa, które $gznalazłeś:znalazłaś;, powinny idealnie posłużyć do wywabienia Lar\'korwiego na otwarty teren. Nie mogę się doczekać wyniku twojej walki z potworem. To olbrzymie bydlę o pazurach ostrych jak najlepsze ostrza. Spojrzysz mu w oczy i ujrzysz śmierć.', 0),
(4292, 'plPL', 'Chwała Matce Ziemi! Udało ci się! Brawo, $N. $GDowiodłeś:Dowiodłaś;, że jesteś $gwielkim łowcą:wielką łowczynią; z prawdziwego zdarzenia. Twój duch jest silny. Twoja odwaga nie ma sobie równych. A twoja siła jeszcze wzrosła. Chylę czoła przed twoimi umiejętnościami.$B$BTylko najwięksi z moich przodków mogliby dokonać czegoś tak niezwykłego. Gratulacje.', 0),
(4301, 'plPL', 'Dobra robota, $N. Jestem zadowolony. $GDokonałeś:Dokonałaś; dziś wielkiej rzeczy.$B$BU\'cha był jedną z największych małp, jakie kiedykolwiek widziałem. To, że $gpokonałeś:pokonałaś; jego siłę, dobrze świadczy o twojej sile... i odwadze.$B$BGodzi się, bym dał ci to w dowód szacunku. $GZasłużyłeś:Zasłużyłaś; na to.', 0),
(4321, 'plPL', 'Dobrze, $N. To fascynujące... Mam tylko nadzieję, że moje diagramy są poprawne! Wszystko zebrałam w tej instrukcji, którą możesz zatrzymać.$B$BMyślę, że teraz odpowiem na wszystkie twoje pytania o kryształy, $N.', 0),
(4381, 'plPL', 'Układasz kryształy na stole i starannie dopasowujesz kolory. Gdy wsuwasz ostatni na miejsce, rozbłysk światła stapia kryształy w jedno.$B$BPowstałe połączenie należy teraz do ciebie.', 0),
(4382, 'plPL', 'Układasz kryształy na stole i starannie dopasowujesz kolory. Gdy wsuwasz ostatni na miejsce, rozbłysk światła stapia kryształy w jedno.$B$BPowstałe połączenie należy teraz do ciebie.', 0),
(4383, 'plPL', 'Układasz kryształy na stole i starannie dopasowujesz kolory. Gdy wsuwasz ostatni na miejsce, rozbłysk światła stapia kryształy w jedno.$B$BPowstałe połączenie należy teraz do ciebie.', 0),
(4384, 'plPL', 'Układasz kryształy na stole i starannie dopasowujesz kolory. Gdy wsuwasz ostatni na miejsce, rozbłysk światła stapia kryształy w jedno.$B$BPowstałe połączenie należy teraz do ciebie.', 0),
(4385, 'plPL', 'Układasz kryształy na stole i starannie dopasowujesz kolory. Gdy wsuwasz ostatni na miejsce, rozbłysk światła stapia kryształy w jedno.$B$BPowstałe połączenie należy teraz do ciebie.', 0),
(4386, 'plPL', 'Układasz kryształy na stole i starannie dopasowujesz kolory. Gdy wsuwasz ostatni na miejsce, rozbłysk światła stapia kryształy w jedno.$B$BPowstałe połączenie należy teraz do ciebie.', 0),
(4491, 'plPL', 'Ringo nie jest w najlepszej formie, $N, ale cieszę się, że wrócił w jednym kawałku!$b$bDziękuję, że go $godnalazłeś:odnalazłaś;.', 0),
(4492, 'plPL', 'Och... Tak się cieszę, że ktoś mnie znalazł...', 0),
(4501, 'plPL', 'Okropnie boję się tutejszych pterrordaksów! Dziękuję, że $gprzetrzebiłeś:przetrzebiłaś; ich szeregi, $N. Teraz może poczuję się na tyle bezpiecznie, by wychylić nos poza Schronienie Marshala.', 0),
(4503, 'plPL', 'Tak, te łuski są idealne. Z nimi na pewno uda mi się poderwać to latadło z ziemi!$B$BDzięki!', 0),
(5150, 'plPL', 'Gdy kładziesz przed nią kiełki, Dadanga wydaje się zadowolona.$B$BW zamian za przysmak podsuwa ci małą paczkę w brązowym papierze!', 0),
(9051, 'plPL', 'Dziękuję, $N. Jesteś $godważny:odważna; i $gmądry:mądra;.$B$BPowiedz mi, jak diabłozaur zareagował na toksynę?', 0),
(9052, 'plPL', 'Nareszcie składniki!$B$BZ ziemią z Un\'Goro, którą zebrałem, łatwo przyrządzę toksynę...', 0),
(9053, 'plPL', 'Nareszcie można stworzyć pełną toksynę. Nie śmiem prosić, byś znów $gugodził:ugodziła; nią to stworzenie – i tak prosiłem już o zbyt wiele.$B$BMasz moją wdzięczność i szacunek. Niech ci się wiedzie w podróżach, $N.', 0),
(12547, 'plPL', '<Słyszysz dudniący zgrzyt kamienia, gdy kończyny Etymidiana budzą się do życia.>$B$BJestem gdzieś potrzebny?', 0),
(12548, 'plPL', '<Gdy odczytujesz ryty na tym kamiennym kolosie, uświadamiasz sobie, że to broń, o której mówiła Freja. To jest Etymidian.>', 0),
(12797, 'plPL', 'Dobrze się $gspisałeś:spisałaś;.$b$bBiada naszym wrogom. Biada tym, którzy służą Królowi Liszowi i zagrażają dziełom tytanów – bo Etymidian już tu jest.', 0),
(13850, 'plPL', 'Udało ci się? Naprawdę ci się udało?!$b$bHo, ho! Uparciuch z ciebie jak moja żona.', 0),
(13887, 'plPL', 'Dobra robota. Szczerze mówiąc, dziwię się, że $gznalazłeś:znalazłaś; ich aż tyle. Z każdym lęgiem jest ich jakby mniej.$b$bPozwolę ci wychować jedno ze świeżo wyklutych jadoskórych. Nie będzie się krępować, żeby dać ci znać, czego potrzebuje.', 0),
(13889, 'plPL', 'Pisklę jadoskórego wydaje się zadowolone z ogromnego posiłku, który mu $gdałeś:dałaś;, ale nie sposób przewidzieć, kiedy znów zgłodnieje.', 0),
(13903, 'plPL', 'Twoje pisklę jadoskórego obdarza cię zębatym uśmiechem, po czym układa się do drzemki.', 0),
(13904, 'plPL', 'Po pożarciu posiłku z jaj silithida twoje pisklę oblizuje się. Przez chwilę masz wrażenie, że jest rozczarowane końcem karmienia.', 0),
(13905, 'plPL', 'Pisklę jadoskórego przyjmuje pióra i zaczyna je oglądać, przykładając kilka z nich do swoich opasek.', 0),
(13906, 'plPL', 'Wygląda na to, że oboje zdołaliście trochę podrosnąć i się nie pozabijać.$b$bNo, wszystko gotowe. Wytresowałem twojego jadoskórego plądrozaura, żeby przybiegał, gdy zadmiesz w ten gwizdek.$b$bNiewielu ma dość zapału, by karmić jadoskórego z ręki i go wychować, ale to naprawdę warte wysiłku.', 0),
(13914, 'plPL', 'Pisklę jadoskórego przyjmuje pióra i zaczyna je oglądać, przykładając kilka z nich do swoich opasek.', 0),
(13915, 'plPL', 'Pisklę jadoskórego wydaje się zadowolone z ogromnego posiłku, który mu $gdałeś:dałaś;, ale nie sposób przewidzieć, kiedy znów zgłodnieje.', 0),
(13916, 'plPL', 'Po pożarciu posiłku z jaj silithida twoje pisklę oblizuje się. Przez chwilę masz wrażenie, że jest rozczarowane końcem karmienia.', 0),
(13917, 'plPL', 'Twoje pisklę jadoskórego obdarza cię zębatym uśmiechem, po czym układa się do drzemki.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(974, 'plPL', 'Poszedłbym tam sam, ale... trochę boję się tamtejszych żywiołaków ognia!', 0),
(3845, 'plPL', 'Cześć. Już cię gdzieś widziałem... Prawda?', 0),
(3881, 'plPL', 'Jeśli mamy mieć jakąkolwiek szansę wydostać się stąd żywi, potrzebujemy naszej dużej skrzyni z żywnością. A odzyskanie choćby części sprzętu badawczego byłoby promykiem nadziei w morzu nieszczęścia.', 0),
(3882, 'plPL', 'Myśl sobie o mnie, co chcesz, ale im będzie wszystko jedno, czy kości do badań pochodzą z pradawnych stegodonów i diemetradonów, czy z tych, które omal nas nie pożarły, kiedy próbowaliśmy rozbić obozy. Ja się ucieszę, jeśli tylko wyjdziemy stąd żywi...', 0),
(3883, 'plPL', 'Masz dla mnie próbkę z roju Gorishi do zbadania, $N?', 0),
(3884, 'plPL', 'Witaj! Ja i moi towarzysze cieszymy się, że widzimy tu jakieś żywe istoty inne niż wyrośnięte, dzikie bestie! Co cię sprowadza do Krateru Un\'Goro?', 0),
(3908, 'plPL', 'No, no... A więc Linken w końcu zebrał się, żeby przysłać mi swój miecz.', 0),
(3909, 'plPL', 'Już $gwróciłeś:wróciłaś;?', 0),
(3961, 'plPL', 'Witaj znowu, $N!', 0),
(3962, 'plPL', 'Żarobieg jest niemal niezwyciężony za aurą, którą stworzył dzięki Złotemu płomieniowi. Tylko ty możesz ją zdjąć Srebrnym totemem Aquementasa.', 0),
(4141, 'plPL', 'Larion jeszcze za swoje dostanie, to pewne!', 0),
(4144, 'plPL', 'Oto plan, $n: idź i zbierz kiełki krwawopłatka – no wiesz, rośliny, które jeszcze w pełni nie wykiełkowały – i przynieś je tutaj. Potem zobaczę, co zdziała z nimi mgiełka Atal\'ai.$B$BMożesz uważać mnie za mściwego... I właściwie masz rację!$B$BPrawda jest taka, że znam drogę stąd, ale dopóki Larion nie przyzna mi racji, zostaję tutaj!$B$BWięc ruszaj, znajdź te kiełki krwawopłatka i zabawmy się!', 0),
(4145, 'plPL', 'Muigin musi mnie najpierw przeprosić, zanim znów się do niego odezwę!', 0),
(4148, 'plPL', 'Żeby porażacz działał, potrzebuje próbki stworzenia, na które ma działać. Wyrusz w głąb krateru i zbierz kiełek krwawopłatka. Wtedy skalibruję go na małych przyjaciół Muigina...$b$bGdyby nie był taki uparty, bylibyśmy już w drodze do domu... Ale do tego czasu muszę mu pokazać, że jego głupi kawał w ogóle mnie nie rusza!', 0),
(4244, 'plPL', 'Panel, pod którym umieszcza się mithrilową obudowę, wciąż jest zamknięty. Reszta A-Me 01 pozostaje bezwładna.', 0),
(4245, 'plPL', 'Udało ci się pomóc A-Me? Zniszczona mithrilowa obudowa, o której $gwspomniałeś:wspomniałaś;, to trafny trop. Jestem pewna, że jeśli ją wymienisz, A-Me się uruchomi i będzie mogła wrócić do domu.', 0),
(4284, 'plPL', 'Po prostu wiem, że jestem na tropie czegoś ważnego, $N!', 0),
(4285, 'plPL', '$GOdwiedziłeś:Odwiedziłaś; pylon, $N?', 0),
(4287, 'plPL', '$GOdwiedziłeś:Odwiedziłaś; pylon, $N?', 0),
(4288, 'plPL', '$GOdwiedziłeś:Odwiedziłaś; pylon, $N?', 0),
(4289, 'plPL', 'Czyżby tutejsze stworzenia już cię pokonały, $N?$B$BNie zniechęcaj się tak łatwo. Tropienie i pokonywanie małp z Un\'Goro to niełatwe zadanie, nawet dla wielkiego łowcy.', 0),
(4290, 'plPL', 'Nie lekceważ moich słów, $N. Jeśli naprawdę chcesz zmierzyć się z tym stworzeniem, musisz być $gostrożny:ostrożna;... i $gsprytny:sprytna;. Wywabienie Lar\'korwiego i pokonanie go wymaga wielkiej siły i przenikliwości.', 0),
(4291, 'plPL', 'Uważaj, $N. Zbliżenie się do któregokolwiek gniazda z jajami z pewnością sprowokuje matki... nawet jeśli masz już gruczoł od jednej z nich. Matki broniące młodych potrafią być równie zabójcze jak sam Lar\'korwi. Jeśli jednak ci się uda, będziemy mieć pewny sposób, by wywabić Lar\'korwiego z kryjówki.', 0),
(4292, 'plPL', 'Nie pozwól, by strach cię pokonał, $N. Strach to wielki zdrajca... musisz być $gsilny:silna;!$B$BWeź mięso, połóż je w małej dolinie, a potem użyj na nim gruczołu. Dopiero wtedy przyjdzie po ciebie śmierć.', 0),
(4301, 'plPL', 'U\'cha... ta bestia była wspaniała. Ogromna i czerwona, z zębami wielkości sztyletów. Ramiona grube jak pnie drzew i szybkie jak u najszybszego górskiego lwa, jakiego widziałem. Uważaj się za $gszczęściarza:szczęściarę;, że $gtrafiłeś:trafiłaś; na taką próbę odwagi – mój lud potrafił całymi pokoleniami nie widzieć podobnego stworzenia.', 0),
(4381, 'plPL', 'Stół pylonu pozwala łączyć zielone kryształy mocy z żółtymi kryształami mocy.$B$BWedług instrukcji J.D. tego połączenia można użyć do uleczenia siebie lub sojuszników.', 0),
(4382, 'plPL', 'Stół pylonu pozwala łączyć zielone kryształy mocy z niebieskimi kryształami mocy.$B$BWedług instrukcji J.D. tego połączenia można użyć do zwiększenia ducha.', 0),
(4383, 'plPL', 'Stół pylonu pozwala łączyć zielone kryształy mocy z czerwonymi kryształami mocy.$B$BWedług instrukcji J.D. tego połączenia można użyć do wzmocnienia ochrony przed obrażeniami fizycznymi.', 0),
(4384, 'plPL', 'Stół pylonu pozwala łączyć czerwone kryształy mocy z niebieskimi kryształami mocy.$B$BWedług instrukcji J.D. tego połączenia można użyć do osłabienia obrony przeciwnika.', 0),
(4385, 'plPL', 'Stół pylonu pozwala łączyć czerwone kryształy mocy z żółtymi kryształami mocy.$B$BWedług instrukcji J.D. tego połączenia można użyć do wywołania potężnej eksplozji, która zada obrażenia wrogom.', 0),
(4386, 'plPL', 'Stół pylonu pozwala łączyć niebieskie kryształy mocy z żółtymi kryształami mocy.$B$BWedług instrukcji J.D. tego połączenia można użyć do stworzenia tarczy zadającej obrażenia wrogom.', 0),
(4491, 'plPL', 'Tak się martwiłam o Ringo...', 0),
(4492, 'plPL', 'Co... Co?', 0),
(4501, 'plPL', 'Prawdę mówiąc, wcale nie przejmowałam się tymi dziwnymi stworami... Aż do dnia, kiedy zobaczyłam napis na boku wielkiego kamienia.$B$BUWAGA NA PTERRORDAKSY$B$BKto mógł go napisać? Nie wiem, ale to zbyt niepokojące, żeby tak po prostu to zignorować!', 0),
(4503, 'plPL', 'Każdy wspaniały pojazd potrzebuje nazwy... Myślałem, żeby nazwać go... Zaorany!', 0),
(5150, 'plPL', 'Dadanga podnosi na ciebie wzrok, gdy się zbliżasz. Wygląda, jakby na coś liczyła...$B$BPewnie jest głodna!$B$BW kraterze na pewno rośnie coś, co byłoby idealną przekąską dla dużego roślinożercy. Dadanga to duża dziewczynka; cokolwiek jej przyniesiesz, musi tego być sporo!', 0),
(9051, 'plPL', 'Udało ci się uspokoić tę wielką bestię?', 0),
(9053, 'plPL', '$GZdobyłeś:Zdobyłaś; pnącze?', 0),
(12547, 'plPL', '<Gniazdo w kształcie runy na piersi Etymidiana jarzy się słabą mocą.>', 0),
(12675, 'plPL', '$GWróciłeś:Wróciłaś;, $n.', 0),
