INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1371, 'plPL', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\Linken_sepia_256px"/>\n</BODY>\n</HTML>', 0),
(1391, 'plPL', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\Linken_sepia_256px"/>\n</BODY>\n</HTML>', 0),
(1491, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nINSTRUKCJA OBSŁUGI KRYSZTAŁOWEGO PYLONU\n</H1>\n<BR/>\n<P align="center">\n„Przewodnik po zbieraniu i używaniu kryształów mocy z Krateru Un\'Goro”\n</P>\n<BR/>\n<BR/>\n<P align="left">\nRozdział 1: Północny pylon\n</P>\n<BR/>\n<P align="left">\nRozdział 2: Wschodni pylon\n</P>\n<BR/>\n<P align="left">\nRozdział 3: Zachodni pylon\n</P>\n<BR/>\n</BODY>\n</HTML>\n', 0),
(1510, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nINSTRUKCJA OBSŁUGI KRYSZTAŁOWEGO PYLONU\n</H1>\n<BR/>\n<P align="center">\n„Przewodnik po zbieraniu i używaniu kryształów mocy z Krateru Un\'Goro”\n</P>\n<BR/>\n<BR/>\n<P align="left">\nRozdział 1: Północny pylon\n</P>\n<BR/>\n<P align="left">\nRozdział 2: Wschodni pylon\n</P>\n<BR/>\n<P align="left">\nRozdział 3: Zachodni pylon\n</P>\n<BR/>\n</BODY>\n</HTML>\n', 0),
(1511, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nRozdział 1: PÓŁNOCNY PYLON\n</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_mini_north" align="left"/>\n<P align="right">\nPółnocny pylon\n<BR/>\nprzyjmuje\n<BR/>\nżółte, czerwone\n<BR/>\ni zielone\n<BR/>\nkryształy.\n</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="left">\nPylon skupia energię, którą można wytworzyć, używając żółtych kryształów jako głównego źródła mocy.\n</P>\n</BODY>\n</HTML>\n', 0),
(1512, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nPołączenia kryształów w północnym pylonie\n</H1>\n<BR/>\n<P align="left">\nMożliwe są dwa efekty: jeden zadaje obrażenia, drugi je niweluje.\n</P>\n<BR/>\n<P align="left">\nKRYSZTAŁOWY ŁADUNEK: wymaga czerwonych i żółtych kryształów.\n<BR/>\nWywołuje potężną eksplozję.\n</P>\n<BR/>\n<P align="left">\nKRYSZTAŁOWE ODNOWIENIE: wymaga żółtych i zielonych kryształów.\n<BR/>\nOtacza cię leczącą aurą.\n</P>\n</BODY>\n</HTML>\n', 0),
(1513, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nSCHEMAT STOŁU PÓŁNOCNEGO PYLONU\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_north"/>\n</BODY>\n</HTML>', 0),
(1514, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nRozdział 2: WSCHODNI PYLON\n</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_mini_east" align="left"/>\n<P align="right">\nWschodni pylon\n<BR/>\nprzyjmuje\n<BR/>\nniebieskie, żółte\n<BR/>\ni zielone\n<BR/>\nkryształy.\n</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="left">\nPylon skupia energię, którą można wytworzyć, używając niebieskich kryształów jako głównego źródła mocy.\n</P>\n</BODY>\n</HTML>\n', 0),
(1515, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nPołączenia kryształów we wschodnim pylonie\n</H1>\n<BR/>\n<P align="left">\nMożliwe są dwa efekty: jeden zwiększa ducha, drugi tworzy tarczę zadającą obrażenia.\n</P>\n<BR/>\n<P align="left">\nKRYSZTAŁOWA SIŁA: wymaga niebieskich i zielonych kryształów.\n<BR/>\nZwiększa twojego ducha.\n</P>\n<BR/>\n<P align="left">\nKRYSZTAŁOWA IGLICA: wymaga niebieskich i żółtych kryształów.\n<BR/>\nTworzy tarczę, która zadaje obrażenia atakującym.\n</P>\n</BODY>\n</HTML>\n', 0),
(1516, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nSCHEMAT STOŁU WSCHODNIEGO PYLONU\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_east"/>\n</BODY>\n</HTML>', 0),
(1530, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nSCHEMAT STOŁU WSCHODNIEGO PYLONU\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_east"/>\n</BODY>\n</HTML>', 0),
(1531, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nRozdział 3: ZACHODNI PYLON\n</H1>\n<BR/>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_mini_west" align="left"/>\n<P align="right">\nZachodni pylon\n<BR/>\nprzyjmuje\n<BR/>\nczerwone, zielone\n<BR/>\ni niebieskie\n<BR/>\nkryształy.\n</P>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="left">\nPylon skupia energię, którą można wytworzyć, używając czerwonych kryształów jako głównego źródła mocy.\n</P>\n</BODY>\n</HTML>', 0),
(1532, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nPołączenia kryształów w zachodnim pylonie\n</H1>\n<BR/>\n<P align="left">\nMożliwe są dwa efekty: jeden zwiększa twoją ochronę przed obrażeniami, drugi osłabia obronę przeciwnika.\n</P>\n<BR/>\n<P align="left">\nKRYSZTAŁOWA OSŁONA: wymaga czerwonych i zielonych kryształów.\n<BR/>\nZwiększa twój pancerz.\n</P>\n<BR/>\n<P align="left">\nKRYSZTAŁOWY PLON: wymaga niebieskich i czerwonych kryształów.\n<BR/>\nMoże obniżyć pancerz wybranego celu.\n</P>\n</BODY>\n</HTML>', 0),
(1533, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nSCHEMAT STOŁU ZACHODNIEGO PYLONU\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\n</BODY>\n</HTML>', 0),
(1550, 'plPL', '<HTML>\n<BODY>\n<H1 align="center">\nSCHEMAT STOŁU ZACHODNIEGO PYLONU\n</H1>\n<BR/>\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\n</BODY>\n</HTML>', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(9623, 0, 0, 'plPL', 'A-Me dobra. Dobra A-Me. Iść... iść za A-Me. Dom. A-Me iść do dom.'),
(9999, 6, 0, 'plPL', '%s po krótkiej chwili wstaje.'),
(9999, 8, 0, 'plPL', '%s po długiej chwili rozpływa się w powietrzu.'),
(14461, 0, 0, 'plPL', 'Słuchajcie mnie, mieszkańcy Krateru! Przybywam, by wypalić z tej krainy wszelką nieczystość!'),
(14461, 1, 0, 'plPL', 'Gdzie są tak zwani bohaterowie tego świata? Za bardzo się boją, żeby wyjść i się pobawić?'),
(14461, 2, 0, 'plPL', 'Jeszcze o mnie usłyszycie, głupcy! Na koniec wszystko strawi ogień!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(2082, 'plPL', '%s zaczyna tworzyć swoją kopię!', '', 0),
(4837, 'plPL', '%s wali się w pierś, wzywając pomocy!', '', 0),
(4838, 'plPL', '%s wybucha, rozpryskując grudy żrącego szlamu!', '', 0),
(5045, 'plPL', '%s wygląda na zmęczonego. Ziewa i kładzie się obok A-Me 01', '', 0),
(5046, 'plPL', '%s głośno chrapie i przytula się do A-Me 01.', '', 0),
(5047, 'plPL', '', '$GWidziałeś:Widziałaś; te wszystkie cudowne rzeczy w Kraterze Un\'Goro, $n? To po prostu niesamowite. Nie tak niesamowite jak niektóre rzeczy, które potrafię zbudować dzięki moim umiejętnościom inżynieryjnym, ale jak na coś całkiem naturalnego... wcale nie najgorsze.$B$BMój wujek Remtravel uwielbia takie stare miejsca jak to. Trochę idę w jego ślady – też chcę odkrywać nowe rzeczy z zaginionych kultur!', 0),
(5048, 'plPL', '', 'Hmm, nie mam żadnych mithrilowych obudów. Wszystkie mi się skończyły. Tylko tego potrzebujesz, żeby naprawić A-Me? Och, to byłoby fantastyczne!$B$BW cywilizowanym świecie mithrilowe obudowy nie są trudne do zdobycia. Poproś po prostu jakiegoś wprawnego inżyniera, żeby ci ją zrobił. Chyba potrzeba do tego kilku sztabek mithrilu, ale jeśli mi pomożesz, dopilnuję, żebyś $gzostał sowicie nagrodzony:została sowicie nagrodzona;!', 0),
(5049, 'plPL', 'Masz może mithrilowe obudowy?', 'Masz może mithrilowe obudowy?', 0),
(5063, 'plPL', 'Dobra... dobra A-Me. A-Me dobra. Dom. Szukać dom.', '', 0),
(5151, 'plPL', 'Kryształowe pylony z Un\'Goro to dla wszystkich zagadka. Dla nielicznych tutejszych mieszkańców są źródłem legend i wielu domysłów co do ich przeznaczenia.', '', 0),
(5152, 'plPL', 'Zbadaj pylon.', 'Zbadaj pylon.', 0),
(5153, 'plPL', 'Pylon zdaje się dokądś przesyłać dane.$b$bPrzy dokładniejszych oględzinach znajdujesz mały stół z żółtymi, czerwonymi i zielonymi kryształami ułożonymi w coś, co wygląda na konkretny wzór.$B$BPo obu stronach dużego niebieskiego kręgu kryształów leżą mniejsze kręgi: jeden z żółtych, drugi z zielonych kryształów.$B$BStarannie zapamiętujesz, co widzisz, wiedząc, że ktoś może być bardzo ciekaw twojego odkrycia.', '', 0),
(5154, 'plPL', 'Pylon zdaje się dokądś przesyłać dane.$b$bPrzy dokładniejszych oględzinach znajdujesz mały stół z żółtymi, czerwonymi i zielonymi kryształami ułożonymi w coś, co wygląda na konkretny wzór.$B$BPo obu stronach dużego żółtego kręgu kryształów leżą mniejsze kręgi: jeden z czerwonych, drugi z zielonych kryształów.$B$BStarannie zapamiętujesz, co widzisz, wiedząc, że ktoś może być bardzo ciekaw twojego odkrycia.', '', 0),
(5155, 'plPL', 'Pylon zdaje się dokądś przesyłać dane.$b$bPrzy dokładniejszych oględzinach znajdujesz mały stół z czerwonymi, niebieskimi i zielonymi kryształami ułożonymi w coś, co wygląda na konkretny wzór.$B$BPo obu stronach dużego czerwonego kręgu kryształów leżą mniejsze kręgi: jeden z niebieskich, drugi z zielonych kryształów.$B$BStarannie zapamiętujesz, co widzisz, wiedząc, że ktoś może być bardzo ciekaw twojego odkrycia.', '', 0),
(5156, 'plPL', 'A-Me w dom! A-Me dobra! Dobra A-Me. Dom. Dom. Dom.', '', 0),
(5157, 'plPL', 'Źle, $n. $n źle!', '', 0),
(5158, 'plPL', '$n nie krzywdzić A-Me. A-Me dobra.', '', 0),
(5159, 'plPL', 'Niebezpieczeństwo. Niebezpieczeństwo! $n chcieć skrzywdzić A-Me.', '', 0),
(5270, 'plPL', 'Tajemnice ukryte w pylonach Krateru Un\'Goro należą teraz do ciebie. Odwiedzaj pylony w dowolnej chwili, by korzystać z ich mocy i zdobywać przydatne zasoby.', '', 0),
(5391, 'plPL', 'Cóż, nie wiem, jak daleko zajdę w takim stanie... Trochę mi słabo...', '', 0),
(5392, 'plPL', 'Jeśli będę wyglądał na zamroczonego, daj mi w twarz. Jeśli zemdleję, użyj manierki. No to w drogę!', '', 0),
(5393, 'plPL', '%s mdleje i pada na ziemię.', '', 0),
(5394, 'plPL', 'Uuuuuuuuuuuuch....', '', 0),
(5395, 'plPL', 'Nie czuję się najlepiej...', '', 0),
(5396, 'plPL', 'Ten upał... Nie wytrzymam...', '', 0),
(5397, 'plPL', 'Może... $gmógłbyś:mogłabyś; mnie ponieść?', '', 0),
(5398, 'plPL', 'Tak, muszę iść dalej.', '', 0),
(5399, 'plPL', 'Czuję się już trochę lepiej, dziękuję.', '', 0),
(5401, 'plPL', 'Jak się czuję? Całkiem przemoczony, dziękuję.', '', 0),
(5402, 'plPL', 'Spraggle! Nie myślałem, że uda mi się wrócić!', '', 0),
(5403, 'plPL', 'Och... Robi mi się słabo...', '', 0),
(5404, 'plPL', 'Uch.', '', 0),
(5405, 'plPL', '', 'Ringo! Nic ci nie jest!', 0),
(5406, 'plPL', '', 'Ringo? Obudź się! Nie martw się, zaopiekuję się tobą.', 0),
(5433, 'plPL', 'Na wszystko, co święte i drogie, powiedz, że $gprzybyłeś:przybyłaś;, by wybawić nas z tej przeklętej krainy. Choć należę do Ekspedycji Marshala, oddałbym ci złote zęby z własnych ust, żeby wejść do twojego plecaka i opuścić to miejsce.', '', 0),
(5434, 'plPL', '', 'Och, witaj! Jestem Hol\'anyee, główna naukowczyni i biolożka Ekspedycji Marshala. Razem z bratem i towarzyszami przemierzamy Azeroth, badając dziki i nieokiełznany majestat przyrody. To ekscytujące... ale, hm... chyba tym razem wpakowaliśmy się w trochę za dużo emocji!', 0),
(5435, 'plPL', 'Witaj, $gnieznajomy:nieznajoma;, w nieokiełznanym majestacie Krateru Un\'Goro!$B$BNazywam się Williden Marshal. Moja siostra, nasi towarzysze i ja tworzymy Ekspedycje Marshala – jesteśmy naukowcami i odkrywcami wielkich, dzikich i nieznanych zakątków Azeroth.', '', 0),
(5512, 'plPL', 'Co myślisz o Dadandze?', 'Co myślisz o Dadandze?', 0),
(5694, 'plPL', 'Tak, tak, wiem, że Dadanga nie lubi dymu. Sądząc jednak po zapachu, Dadanga nie lubi też kąpieli.', '', 0),
(5763, 'plPL', 'Święty Krakle! Temperatura wynosi 428 000 stopni Kraklenheita!', '', 0),
(5764, 'plPL', 'Temperatura wynosi 9280 stopni Kraklenheita! GORĄCO!', '', 0),
(5765, 'plPL', 'Temperatura wynosi 564 stopnie Kraklenheita.', '', 0),
(5766, 'plPL', 'Temperatura wynosi 122 stopnie Kraklenheita.', '', 0),
(5767, 'plPL', 'Temperatura wynosi 12 stopni Kraklenheita. Ależ emocje.', '', 0),
(5923, 'plPL', '', 'Witaj w Schronieniu, $n. Niektórzy przychodzą tu w jakimś celu, inni trafili tu przypadkiem... Ale każdy tutaj ma do opowiedzenia wyjątkową historię.', 0),
(6006, 'plPL', '428 000 stopni Kraklenheita... Co tam, gorąca sztuko!?', '', 0),
(6007, 'plPL', 'DING! 428 000 stopni Kraklenheita, co do joty! No, w przybliżeniu. Prawie. Gdzieś koło tego...', '', 0),
(6008, 'plPL', 'Mierząc w skali Kraklenheita, jest 428 000 stopni! Ale krakleńsko!', '', 0),
(6009, 'plPL', '18 stopni Kraklenheita. Właściwie jest dość zimno...', '', 0),
(6010, 'plPL', 'Jest 40 stopni Kraklenheita. Czujesz ten żar? Nie? Ja też nie bardzo.', '', 0),
(6011, 'plPL', 'O rany, 3 stopnie Kraklenheita. Szukaj dalej.', '', 0),
(6314, 'plPL', 'Och!!! Zabierz to ode mnie!', '', 0),
(6317, 'plPL', 'Czemu mnie gonisz, mechaniczny yeti?! CZEMU?!', '', 0),
(6318, 'plPL', '%s szybko ucieka przed Mechanicznym yeti Umi.', '', 0),
(6320, 'plPL', 'I tak jestem nerwowy... a ludzie jeszcze uparcie mnie straszą... Ale następnym razem będę gotowy!', '', 0),
(6322, 'plPL', '%s wygląda na uspokojonego.', '', 0),
(9744, 'plPL', '', 'Cóż za wspaniały dzień, by żyć! Spójrz, jakie piękno cię otacza, przyjacielu. Ciesz się tym, co daje życie!', 0),
(9745, 'plPL', '*GRRRR* *HAU* *HAU*', '', 0),
(9755, 'plPL', 'Nie zwiedzie mnie twoje przebranie, kusicielko. Nadeszła twoja godzina.', 'Nie zwiedzie mnie twoje przebranie, kusicielko. Nadeszła twoja godzina.', 0),
(11606, 'plPL', 'Gdzie jest Nestor Pieśń Ostrza?', 'Gdzie jest Nestor Pieśń Ostrza?', 0),
(11607, 'plPL', 'W Twierdzy Druidów w Silithusie przebywa Nestor Pieśń Ostrza.', 'W Twierdzy Druidów w Silithusie przebywa Nestor Pieśń Ostrza.', 0),
(11608, 'plPL', 'Gdzie jest Nestor Pierwokamień?', 'Gdzie jest Nestor Pierwokamień?', 0),
(11609, 'plPL', 'Nestor Pierwokamień od wielu lat przebywa w Kryształowej Dolinie w Silithusie.', 'Nestor Pierwokamień od wielu lat przebywa w Kryształowej Dolinie w Silithusie.', 0),
(28569, 'plPL', '', 'Plaga to skaza na tych nieskalanych ziemiach. Mocą moich stwórców zmiażdżę pod stopą każdą, co do jednej, z ich zmurszałych kości.', 0),
(28583, 'plPL', 'Chcę powstrzymać Plagę tak samo jak ty. Jak mogę pomóc?', 'Chcę powstrzymać Plagę tak samo jak ty. Jak mogę pomóc?', 0),
(28584, 'plPL', '', 'Tytani nie stworzyli życia w jedną noc. Był to stopniowy proces, który wymagał wielu eksperymentów i kolejnych prób.$B$BWłaśnie dlatego istnieją tak pilnie strzeżone miejsca jak Kotlina Sholazar.$B$BBy zapewnić bezpieczeństwo swoim poligonom doświadczalnym, tytani stworzyli mechanizm obronny. Jego niszczycielska siła nie ma jednak sobie równych i nie wyjawię nic więcej, dopóki nie przysięgniesz wierności mojej sprawie.', 0),
(28585, 'plPL', '', 'To graniczy ze świętokradztwem, by wyjawiać te tajemnice śmiertelnikowi takiemu jak ty, ale nie mam wielkiego wyboru.$B$BOdkąd Freja, córa tytanów, zostawiła mnie tutaj, mam tylko jedno zadanie i nie mogę zawieść. Życie trzeba chronić za wszelką cenę.$B$BIstnieją wrota przejścia, które łączą to miejsce z innym, bardzo do niego podobnym. To tam znajduje się broń, której szukamy.', 0),
(28586, 'plPL', 'Możesz mi zaufać. Nie jestem $gprzyjacielem:przyjaciółką; Króla Lisza.', 'Możesz mi zaufać. Nie jestem $gprzyjacielem:przyjaciółką; Króla Lisza.', 0),
(28587, 'plPL', 'Nie zawiodę.', 'Nie zawiodę.', 0),
(29968, 'plPL', '$GGłupcze:Głupia;! $GDoprowadziłeś:Doprowadziłaś; nas do jedynej istoty, która mogła stawić czoła naszym armiom! Nigdy nie sprowadzisz Etymidiana do Północnej Grani!', '', 0),
